import type { FestiveThemeId } from "@/lib/festive-themes";

/**
 * The actual festival artwork — the things somebody recognises at a
 * glance: a marigold toran for Diwali, a pine-and-bauble garland for
 * Christmas, bunting for Holi, and Santa's sleigh crossing the screen.
 *
 * ── WHY PRIMITIVES AND NOT HAND-WRITTEN PATHS ─────────────────────────
 * Every shape here is built from circles, ellipses, polygons and short
 * quadratic curves, and the repeating parts are generated by mapping
 * over an array. Long hand-authored `d` attributes are the classic way
 * to get art that looks almost right and is impossible to adjust — and
 * they cannot be reviewed, because nobody can read a 400-character
 * path. These can be tuned by changing a number.
 *
 * Everything is `currentColor`-free and takes explicit colours, so the
 * same component serves the web page and the admin preview without
 * inheriting a surprise from whatever it is nested in.
 */

/** A marigold: a ring of petals around a lighter centre. */
export function Marigold({ size = 22, outer, inner }: { size?: number; outer: string; inner: string }) {
  const petals = Array.from({ length: 12 }, (_, i) => i * 30);
  return (
    <svg width={size} height={size} viewBox="0 0 24 24" aria-hidden="true">
      <g>
        {petals.map((deg) => (
          <ellipse
            key={deg}
            cx="12"
            cy="5.6"
            rx="2.5"
            ry="4.4"
            fill={outer}
            transform={`rotate(${deg} 12 12)`}
          />
        ))}
        <circle cx="12" cy="12" r="4.6" fill={inner} />
        <circle cx="12" cy="12" r="2.2" fill={outer} opacity="0.75" />
      </g>
    </svg>
  );
}

/** A mango leaf — the other half of a real toran. */
export function MangoLeaf({ size = 20, color = "#15803d" }: { size?: number; color?: string }) {
  return (
    <svg width={size} height={size * 1.3} viewBox="0 0 24 32" aria-hidden="true">
      <path
        d="M12 1 C19 9, 19 23, 12 31 C5 23, 5 9, 12 1 Z"
        fill={color}
      />
      <path d="M12 3 L12 29" stroke="#052e16" strokeWidth="1" opacity="0.5" />
    </svg>
  );
}

/** A Christmas bauble on its cap. */
export function Bauble({ size = 18, color }: { size?: number; color: string }) {
  return (
    <svg width={size} height={size * 1.25} viewBox="0 0 20 25" aria-hidden="true">
      <rect x="8" y="0" width="4" height="4" rx="1" fill="#d4d4d8" />
      <circle cx="10" cy="14" r="9" fill={color} />
      <ellipse cx="6.5" cy="10" rx="2.2" ry="3" fill="#ffffff" opacity="0.35" />
    </svg>
  );
}

/** A sprig of pine. */
export function PineSprig({ size = 26, color = "#166534" }: { size?: number; color?: string }) {
  const rows = [0, 1, 2];
  return (
    <svg width={size} height={size} viewBox="0 0 28 28" aria-hidden="true">
      {rows.map((r) => (
        <polygon
          key={r}
          points={`14,${2 + r * 7} 6,${12 + r * 6} 22,${12 + r * 6}`}
          fill={color}
          opacity={0.9 - r * 0.1}
        />
      ))}
    </svg>
  );
}

/** A bunting flag, for Holi. */
export function Flag({ size = 22, color }: { size?: number; color: string }) {
  return (
    <svg width={size} height={size * 1.2} viewBox="0 0 20 24" aria-hidden="true">
      <polygon points="0,0 20,0 10,22" fill={color} />
    </svg>
  );
}

/**
 * Santa on his sleigh, drawn as a silhouette.
 *
 * Deliberately a silhouette: at the size this crosses the screen,
 * detailed art turns to mush, while an outline of reindeer-reins-sleigh
 * is read instantly. The shape is what carries it, so the fill is a
 * single colour plus one highlight for Santa's trim.
 */
export function SantaSleigh({ width = 190, color = "#fca5a5", trim = "#ffffff" }: {
  width?: number;
  color?: string;
  trim?: string;
}) {
  return (
    <svg width={width} height={width * 0.42} viewBox="0 0 190 80" aria-hidden="true">
      {/* reindeer */}
      <g fill={color}>
        <ellipse cx="38" cy="44" rx="20" ry="9" />
        <ellipse cx="17" cy="35" rx="8" ry="6.5" />
        <polygon points="9,31 2,22 8,27 7,18 12,27" />
        <polygon points="23,30 28,20 25,27 32,23 26,31" />
        <rect x="26" y="50" width="3" height="14" rx="1.5" />
        <rect x="36" y="51" width="3" height="13" rx="1.5" />
        <rect x="46" y="50" width="3" height="14" rx="1.5" />
        <rect x="53" y="51" width="3" height="12" rx="1.5" />
        <path d="M56 40 q 10 -4 14 4" stroke={color} strokeWidth="2.5" fill="none" />
      </g>
      {/* sleigh */}
      <g fill={color}>
        <path d="M86 58 q -4 -22 16 -22 h 48 q 10 0 10 12 v 10 z" />
        <path
          d="M80 62 q 10 8 26 8 h 54 q 10 0 14 -8"
          stroke={color}
          strokeWidth="4"
          fill="none"
          strokeLinecap="round"
        />
      </g>
      {/* santa */}
      <g>
        <circle cx="124" cy="26" r="9" fill={color} />
        <circle cx="124" cy="15" r="5" fill={trim} />
        <rect x="112" y="30" width="24" height="8" rx="4" fill={trim} opacity="0.85" />
      </g>
      {/* a waved arm, because it is what makes it read as Santa and not a cart */}
      <path d="M136 24 q 10 -6 14 -16" stroke={color} strokeWidth="4" fill="none" strokeLinecap="round" />
    </svg>
  );
}

/**
 * An oil lamp with a flame — the thing a scattered dot was standing in
 * for. Small enough to float in a backdrop, specific enough to read as
 * a diya rather than a blob.
 */
export function Diya({ size = 34, clay = "#b45309", flame = "#fde68a", glow = "#fbbf24" }: {
  size?: number;
  clay?: string;
  flame?: string;
  glow?: string;
}) {
  return (
    <svg width={size} height={size * 0.8} viewBox="0 0 40 32" aria-hidden="true">
      <ellipse cx="20" cy="24" rx="15" ry="6" fill={clay} />
      <path d="M5 23 q 15 10 30 0 z" fill="#78350f" />
      <ellipse cx="20" cy="12" rx="6" ry="9" fill={glow} opacity="0.35" />
      <path d="M20 4 q 4.5 6 0 13 q -4.5 -7 0 -13 Z" fill={flame} />
    </svg>
  );
}

/** The decorations that hang from the header garland, per theme. */
export function garlandUnit(theme: FestiveThemeId, i: number) {
  if (theme === "diwali") {
    return i % 2 === 0 ? (
      <Marigold size={i % 4 === 0 ? 24 : 19} outer="#f97316" inner="#fde047" />
    ) : (
      <MangoLeaf size={17} />
    );
  }
  if (theme === "christmas") {
    return i % 3 === 1 ? (
      <Bauble size={17} color={i % 2 === 0 ? "#ef4444" : "#fbbf24"} />
    ) : (
      <PineSprig size={24} />
    );
  }
  const colours = ["#e879f9", "#38bdf8", "#facc15", "#4ade80", "#fb7185"];
  return <Flag size={20} color={colours[i % colours.length]} />;
}
